window.EXAUD={"We play badminton in the afternoon.": "../communication/audio/cau/d52865a564c5f8aa.mp3", "On Sunday afternoon, Nam visits his grandparents.": "../communication/audio/cau/b1136001f7e81069.mp3", "Can you say that again, please?": "../a-closer-look-1/audio/cau/7e3810543bbdcfd8.mp3", "Mi read the story again and again.": "../a-closer-look-1/audio/cau/1afa85aeab810227.mp3", "My parents allow me to play games at weekends.": "../a-closer-look-2/audio/cau/0e78db317452b06e.mp3", "The park doesn't allow bikes; it bans them.": "../a-closer-look-2/audio/cau/cf368ad5bb4a58ec.mp3", "Lan likes music. She also likes drawing.": "../communication/audio/cau/a42927a6760bdc56.mp3", "Nam speaks English and also learns Japanese.": "../communication/audio/cau/d657bddc45a35d0d.mp3", "My mother always gets up early.": "../a-closer-look-2/audio/cau/018f205f8d900a21.mp3", "Nam always does his homework, but he never watches TV late.": "../a-closer-look-2/audio/cau/bed514ec413923ae.mp3", "I am a student at Kim Dong School.": "../a-closer-look-1/audio/cau/7c9effe742362b92.mp3", "I am in Class 6A, and my friends are in 6B.": "../a-closer-look-1/audio/cau/69bce6abc68e1822.mp3", "Ha Long Bay is amazing.": "../getting-started/audio/cau/94ed67ada3a0dcec.mp3", "What an amazing show!": "../getting-started/audio/cau/ec1c0446de9b7767.mp3", "My brother loves drawing animals.": "audio/cau/05c49969296ecc10.mp3", "A cat is a small animal, but an elephant is big.": "audio/cau/6225cb8856b5304b.mp3", "Lan eats an apple every morning.": "../a-closer-look-2/audio/cau/79c041305a2e80c6.mp3", "Apple is a big company that makes phones and computers.": "../a-closer-look-2/audio/cau/d8d1d310f9c383bb.mp3", "Mi and Nam are in Class 6A.": "../a-closer-look-1/audio/cau/b0d165e52ca7dc85.mp3", "We are happy today, and Lan is happy too.": "../a-closer-look-1/audio/cau/9718e7702bade08e.mp3", "They aren't at home now.": "../looking-back/audio/cau/6f3733b344f72b2c.mp3", "We aren't late; we are early.": "../looking-back/audio/cau/66e583dcb1eb30f3.mp3", "Hoan Kiem Lake is a popular attraction.": "../looking-back/audio/cau/94088e7e8cf750d8.mp3", "The night market attracts tourists and is a big attraction.": "../looking-back/audio/cau/5a512b8768f85428.mp3", "He came back to his village after the war.": "../a-closer-look-1/audio/cau/97697c4a9d748fa3.mp3", "Nam went to Hue and came back on Sunday.": "../a-closer-look-1/audio/cau/1bf8eb10f268125e.mp3", "My backpack is very heavy.": "../a-closer-look-1/audio/cau/707bbe4f5a7af52f.mp3", "Put your water in your backpack.": "../a-closer-look-1/audio/cau/6fc7cb9e80f2aea4.mp3", "My school bag is very heavy.": "../a-closer-look-1/audio/cau/81c86f54e6817fa3.mp3", "Mi has a red bag, and Lan has two blue bags.": "../a-closer-look-1/audio/cau/33eb6b7417d04199.mp3", "The school bans phones in class.": "../getting-started/audio/cau/b0af45ee2d92cbd2.mp3", "Smoking is banned here.": "../getting-started/audio/cau/123fbc274f4b91a5.mp3", "There is a banana on the table.": "../a-closer-look-2/audio/cau/4b32a815ce7c415c.mp3", "Lan eats a banana, and her brother eats two bananas.": "../a-closer-look-2/audio/cau/402d6fa42a7db173.mp3", "We heard a loud bang outside.": "../getting-started/audio/cau/70bde59a5acdaf16.mp3", "Don't bang the door!": "../getting-started/audio/cau/714f279c82c4b50e.mp3", "Ha Long Bay is a World Heritage Site.": "../a-closer-look-2/audio/cau/5a085a89254963b8.mp3", "There are thousands of islands in the bay.": "../a-closer-look-2/audio/cau/4cf873f6cc8fd985.mp3", "Please be quiet in the library.": "../a-closer-look-1/audio/cau/d6fab02a2655be4e.mp3", "I want to be a doctor. My sister is a nurse.": "../a-closer-look-1/audio/cau/e31166f3ca032296.mp3", "It's sunny. Let's go to the beach.": "../a-closer-look-1/audio/cau/270a764075ddb193.mp3", "My Khe Beach in Da Nang is very beautiful.": "../a-closer-look-1/audio/cau/c42618aa030cc85a.mp3", "Hoi An is a beautiful old town.": "../getting-started/audio/cau/e98bb193dd75aa2b.mp3", "Lan sings beautifully, and her voice is beautiful.": "../getting-started/audio/cau/4d5c5951771c97b1.mp3", "I go to bed at ten o'clock.": "../a-closer-look-1/audio/cau/37f1c2a86a0f3867.mp3", "There is a bed and a desk in my bedroom.": "../a-closer-look-1/audio/cau/5306adc35ff279d9.mp3", "Lan is my best friend.": "../skills-1/audio/cau/9edc7bdf247f31c3.mp3", "Mi's drawing is good, Nam's is better, but Hoa's is the best.": "../skills-1/audio/cau/c2336133ff2dce7f.mp3", "I ride my bicycle to school every day.": "../communication/audio/cau/dcdb6e0b40d1db18.mp3", "Nam's bicycle is new, and he loves his bike.": "../communication/audio/cau/11b6650e5706243d.mp3", "Our school has a big garden.": "../a-closer-look-2/audio/cau/6b86817f41024790.mp3", "My house is big, but Minh's house is bigger.": "../a-closer-look-2/audio/cau/1d7d2b8d19284673.mp3", "Ho Chi Minh City is bigger than Da Nang.": "../getting-started/audio/cau/5efe9fe286047142.mp3", "My house is big, but Nam's house is bigger.": "../getting-started/audio/cau/44f8b6366001f6da.mp3", "This is the biggest market in the city.": "../getting-started/audio/cau/ba6358ef44b7b295.mp3", "Ho Chi Minh City is the biggest city in Viet Nam.": "../getting-started/audio/cau/815c69dda42327e1.mp3", "Please put your rubbish in the bin.": "../looking-back/audio/cau/3797d15061da27bc.mp3", "There are two bins: one for paper and one for plastic.": "audio/cau/4a7ce4dcbc80665d.mp3", "Happy birthday, Mi!": "../looking-back/audio/cau/f1ae6fa2fd0a78d1.mp3", "Nam was born in May, so his birthday is in May.": "../looking-back/audio/cau/870217b5fec80b92.mp3", "My grandpa goes to the market by boat.": "../a-closer-look-1/audio/cau/144e963c57b5e9ec.mp3", "There are many boats on the Mekong River.": "../a-closer-look-1/audio/cau/b99180aa114c4718.mp3", "I like reading books about animals.": "../a-closer-look-2/audio/cau/161e5202b70a9850.mp3", "This book is mine, and those books are Nam's.": "../a-closer-look-2/audio/cau/564922fbe3abbd87.mp3", "The film was long and boring.": "../skills-1/audio/cau/2fb37c98bad76a4f.mp3", "The lesson was boring, so Nam felt bored.": "../skills-1/audio/cau/0b9b11807d964d8b.mp3", "I bring a bottle of water to school.": "../looking-back/audio/cau/433914abdbfc6745.mp3", "Don't throw plastic bottles away.": "../looking-back/audio/cau/266d8c66dc2acf68.mp3", "We can recycle plastic bottles.": "audio/cau/a053d1cc04823f7e.mp3", "She made flower pots from old bottles.": "audio/cau/47ed22e5783f210e.mp3", "The boy next to Mi is my brother.": "audio/cau/2b8e169ba1253282.mp3", "There are ten boys and twelve girls in my class.": "audio/cau/f109fb5b9db06caa.mp3", "I have bread and milk for breakfast.": "../a-closer-look-2/audio/cau/52bab63d80c6e149.mp3", "Mum bought a loaf of bread at the bakery.": "../a-closer-look-2/audio/cau/3fb4b6c8304d8552.mp3", "Please bring your English book tomorrow.": "../a-closer-look-2/audio/cau/cd49561735d6690b.mp3", "Exams can bring about a lot of stress.": "../a-closer-look-2/audio/cau/4bcd1f108e558b55.mp3", "The craft village brings jobs to local people.": "../communication/audio/cau/0e7f9b2836ed98fa.mp3", "Tourism brings money, and last year it brought many visitors.": "../communication/audio/cau/c12b6a42eae46d36.mp3", "I like bread with butter.": "../a-closer-look-2/audio/cau/f6f92d67fb281e30.mp3", "Add some butter to the pan.": "../a-closer-look-2/audio/cau/975eb8d1d8487fe0.mp3", "I want to buy a new lamp for my room.": "../a-closer-look-2/audio/cau/f0b3e6851a8b52eb.mp3", "Mum bought a sofa, and Dad wants to sell the old one.": "../a-closer-look-2/audio/cau/59add360cbe991b8.mp3", "How about making a cake for Mum's birthday?": "../looking-back/audio/cau/ac3dd076cc4a499c.mp3", "Lan cuts the birthday cake into eight pieces.": "../looking-back/audio/cau/7f8f4245673c165e.mp3", "We go to a summer camp in July.": "../a-closer-look-1/audio/cau/0cc47306202bf7b0.mp3", "At the camp, Nam and his friends went camping by the lake.": "../a-closer-look-1/audio/cau/62e47843f7db5804.mp3", "Mi can swim very well.": "../a-closer-look-2/audio/cau/3e8edac082144330.mp3", "I can ride a bike now, but last year I couldn't.": "../a-closer-look-2/audio/cau/af33705bbc26781d.mp3", "I can't find my pencil case.": "../communication/audio/cau/eb6d0d717595fc1e.mp3", "Nam can swim, but he can't play the guitar.": "../communication/audio/cau/7d46b51b1e362522.mp3", "Light a candle when the power is off.": "../looking-back/audio/cau/651c1e9112399b16.mp3", "There are twelve candles on the cake.": "../looking-back/audio/cau/dd5c4ce45e4b63fe.mp3", "Blow out the candles!": "../looking-back/audio/cau/259dd69692318aa2.mp3", "We lit candles for the festival.": "../looking-back/audio/cau/598f3404300dd2f3.mp3", "The man is carrying a big basket.": "audio/cau/de3e75eb05b945dd.mp3", "Phong carried the bag yesterday and is carrying it again.": "audio/cau/626aa2d48bd02790.mp3", "There is a cat under the bed.": "../a-closer-look-1/audio/cau/b07c0b9bf36ecd88.mp3", "Our cat has two little kittens.": "../a-closer-look-1/audio/cau/faccccf3b8679bc0.mp3", "Son Doong is the biggest cave in the world.": "../a-closer-look-2/audio/cau/47015280ee85734a.mp3", "We explored a dark cave in Quảng Bình.": "../a-closer-look-2/audio/cau/4fd3beb6a1d030e0.mp3", "There are many beautiful caves in Hạ Long Bay.": "../looking-back/audio/cau/eadee676fef8f769.mp3", "Some caves are very deep.": "../looking-back/audio/cau/8c0071053712f591.mp3", "There are forty students in my class.": "../a-closer-look-2/audio/cau/69f347ac209b4fc2.mp3", "Nam is my classmate. We are in the same class.": "../a-closer-look-2/audio/cau/e6a0aa2aaff4be27.mp3", "Our classroom is on the second floor.": "../a-closer-look-2/audio/cau/c460b559d453bdeb.mp3", "My classmates and I clean the classroom on Fridays.": "../a-closer-look-2/audio/cau/9cf5ce52e3da16c8.mp3", "There is a clock on the wall.": "audio/cau/db00df18f8f94a24.mp3", "Nam has a watch, but his room has no clock.": "audio/cau/93f2ef3a8ab5efe7.mp3", "Let's take a closer look at the words.": "../getting-started/audio/cau/3f25d4a7ecb1e46f.mp3", "Lan's house is close, but Mi's house is closer.": "../getting-started/audio/cau/95aeed65b79a000e.mp3", "I join the English club on Fridays.": "../getting-started/audio/cau/4854d8e45991624d.mp3", "Hoa is in the art club at school.": "../getting-started/audio/cau/1bf4d645fed3a1be.mp3", "Our football coach is very strict.": "../looking-back/audio/cau/725309a0996d6b5f.mp3", "We went to Đà Nẵng by coach.": "../looking-back/audio/cau/610e1d15d3b888f5.mp3", "Wear a warm coat when it is cold outside.": "../communication/audio/cau/d5e8abe0718f528b.mp3", "Lan forgot her coat and caught a cold.": "../communication/audio/cau/47f6fc0e90e11519.mp3", "I came down with a cold last week.": "../a-closer-look-1/audio/cau/6589d8d2056f15e9.mp3", "It is cold in Ha Noi in winter.": "../a-closer-look-1/audio/cau/6af5e5587fe6cf7a.mp3", "Communication is important in a team.": "audio/cau/ceae7194d8982d8f.mp3", "We communicate in English to improve our communication skills.": "audio/cau/78dbdceb83728ae8.mp3", "Use a compass to find the way.": "../a-closer-look-1/audio/cau/6f8967d642f36613.mp3", "I draw circles with a compass.": "../a-closer-look-1/audio/cau/6a4c4bfbb3147477.mp3", "Look at picture d and answer the question.": "../a-closer-look-1/audio/cau/cd1db823a64876e3.mp3", "Choose answer d, then write it in your notebook.": "../a-closer-look-1/audio/cau/d8924058670ef40e.mp3", "Playing on the road is dangerous.": "../looking-back/audio/cau/3bf8cadff14ebae2.mp3", "Fire is a danger, so it is dangerous to play with matches.": "../looking-back/audio/cau/0f659a664b64ff32.mp3", "Hoa's mother cooks delicious pho.": "../skills-2/audio/cau/8a832f4b8fdda704.mp3", "If I have all the ingredients, I can make a delicious pizza.": "../skills-2/audio/cau/5f9d8db4e0198b83.mp3", "The Sahara is the largest hot desert.": "../a-closer-look-1/audio/cau/b5ab545ec1917b35.mp3", "Camels can live in the desert.": "../a-closer-look-1/audio/cau/c06453c4acef7e3c.mp3", "My house is different from yours.": "../getting-started/audio/cau/5abda8894fc87510.mp3", "Lan and Mi are different; the difference is their hobbies.": "../getting-started/audio/cau/fd7e006914631783.mp3", "I do my homework after dinner.": "../a-closer-look-1/audio/cau/dfa2558950305f83.mp3", "Phong did his homework, and now it is done.": "../a-closer-look-1/audio/cau/4e496982963ec9df.mp3", "Does Lan like ice cream?": "../a-closer-look-1/audio/cau/15298c934c7dedf6.mp3", "Nam does his homework, but he doesn't watch TV.": "../a-closer-look-1/audio/cau/16100881d98fba74.mp3", "Mi doesn't like milk very much.": "../communication/audio/cau/63a58b0dc618ef2d.mp3", "Nam does his homework, but Minh doesn't do it.": "../communication/audio/cau/362bb11ca0696388.mp3", "I don't like rainy days.": "../a-closer-look-2/audio/cau/111328217b7f4b84.mp3", "We don't play games, but Minh does.": "../a-closer-look-2/audio/cau/851ce9fc9da85e82.mp3", "This notebook costs fifteen thousand dong.": "audio/cau/73acc66c00944007.mp3", "I paid twenty thousand dong for the bread.": "audio/cau/757309fc5d7a69ee.mp3", "The Sahara has many large sand dunes.": "../getting-started/audio/cau/c5efd88634e564d8.mp3", "Children love sliding down the dunes.": "../getting-started/audio/cau/051298f6fade29ff.mp3", "Do exercise e on page ten.": "../a-closer-look-1/audio/cau/f397a6a2157f10ba.mp3", "The word 'eye' starts with the letter e.": "../a-closer-look-1/audio/cau/5f2132c30b4b4b2f.mp3", "Steve Jobs' early life was not easy.": "../skills-1/audio/cau/870d0cf6ff3509a5.mp3", "Lan came early, but Nam came late.": "../skills-1/audio/cau/c338abccaad4e9f4.mp3", "We eat rice every day.": "../a-closer-look-1/audio/cau/e1b9f1e0ff973ad1.mp3", "We eat rice today, but yesterday we ate pho.": "../a-closer-look-1/audio/cau/575ec69b6a817f1a.mp3", "What else can we do to stay healthy?": "../communication/audio/cau/10a061b0917c9692.mp3", "Ask someone else to help you.": "../communication/audio/cau/21b2214919853b5c.mp3", "I enjoy living in the city.": "../communication/audio/cau/1cc10e53aebeec12.mp3", "We enjoy the trip because it is very enjoyable.": "../communication/audio/cau/1a682a8a24ff63b3.mp3", "Add er to make the comparative: dense becomes denser.": "../a-closer-look-1/audio/cau/80052b55c7afa240.mp3", "Dirty becomes dirtier: change y to i and add er.": "../a-closer-look-1/audio/cau/5c7897723129ca0f.mp3", "City life is exciting for teens.": "../skills-1/audio/cau/28945e456a70e4ca.mp3", "The trip was exciting, so we were very excited.": "../skills-1/audio/cau/53c60dbfd0e789cf.mp3", "We want to explore Phong Nha Cave.": "../a-closer-look-1/audio/cau/fc23cce7fe3d2660.mp3", "Let's explore the old town.": "../a-closer-look-1/audio/cau/53f1bca0671786f2.mp3", "Be careful, or you will fall off your bike.": "../a-closer-look-1/audio/cau/9a84ed98192bb4e5.mp3", "Nam fell asleep during the long film.": "../a-closer-look-1/audio/cau/6973f886bc33cd03.mp3", "Is this sentence true or false?": "../skills-2/audio/cau/b08a12186b6dfb5e.mp3", "That answer is false, but Hoa's answer is true.": "../skills-2/audio/cau/493842939182df2a.mp3", "There are four people in my family.": "audio/cau/8324f70f7fed9e74.mp3", "Many families in my village grow rice.": "audio/cau/5b179b43939643fc.mp3", "Hoi An is famous for its lanterns.": "../communication/audio/cau/be0831db3c3bf621.mp3", "General Giap became famous, and his fame spread worldwide.": "../communication/audio/cau/4eabd5e77fd10a06.mp3", "My favourite room is the kitchen.": "../skills-1/audio/cau/7fe9b9a43268f379.mp3", "Football is Nam's favourite sport.": "audio/cau/5418f30ef37044b0.mp3", "I'm fine, thanks. And you?": "../communication/audio/cau/4ae012a7118588c0.mp3", "The weather is fine today, so we feel well.": "../communication/audio/cau/751a59acef6b991a.mp3", "We buy fresh fish at the market.": "../skills-2/audio/cau/1e1bd5d1bfbdcbed.mp3", "Grandpa goes fishing and catches three fish.": "../skills-2/audio/cau/82e6c573c6d91dda.mp3", "How about putting some flowers on the table?": "../a-closer-look-2/audio/cau/2b9b6c204f34cab8.mp3", "My grandma grows flowers in her garden.": "../a-closer-look-2/audio/cau/8e0ebaa5f0e0c564.mp3", "Follow the steps to make your poster.": "../a-closer-look-1/audio/cau/6579733e7f4abc4a.mp3", "Minh followed his teacher's advice and passed the exam.": "../a-closer-look-1/audio/cau/9fff6306c664e2d9.mp3", "We need food and water every day.": "../a-closer-look-1/audio/cau/01b6dc39aa643a2b.mp3", "Mum feeds the baby healthy food.": "../a-closer-look-1/audio/cau/1407b84140607171.mp3", "Many animals live in the forest.": "../a-closer-look-1/audio/cau/de5591cef1bfa727.mp3", "We went camping in the forest.": "../a-closer-look-1/audio/cau/81f5245d16792b64.mp3", "Don't forget your homework!": "../communication/audio/cau/42bcd3e580da9477.mp3", "Hoa forgot her book, but she remembered her pen.": "../communication/audio/cau/4fd2b5e71375a59b.mp3", "We buy fresh fish and vegetables at the market.": "../skills-2/audio/cau/61ee9997ca99fa08.mp3", "The air here is fresh, fresher than in the city.": "../skills-2/audio/cau/04d4e324c4c12ce3.mp3", "There is some milk in the fridge.": "../a-closer-look-2/audio/cau/5fbcf64ec9261d1b.mp3", "Put the fresh fish in the fridge, please.": "../a-closer-look-2/audio/cau/cd244989781db9da.mp3", "Lan is my good friend.": "../skills-1/audio/cau/dd872f787d0777d3.mp3", "My friend Minh is very friendly.": "../skills-1/audio/cau/4f7040d4f93a465f.mp3", "We have geography on Tuesday.": "../getting-started/audio/cau/0fb38fe2833d53d4.mp3", "I learn about rivers in geography.": "../getting-started/audio/cau/e611a28e72272a8c.mp3", "It's getting dark, so let's go home.": "audio/cau/a5d44c2a5398af17.mp3", "Minh got up late, so he is getting ready quickly.": "audio/cau/be131cb99a335b88.mp3", "My teacher gives us a lot of homework.": "audio/cau/9e792e0228b9fc48.mp3", "Mi always gives good advice, and she gave me some today.": "audio/cau/9d8952d03493a72d.mp3", "I go to school by bike.": "../a-closer-look-1/audio/cau/df5dcef1ab40916f.mp3", "We often go to the beach; last summer we went to Nha Trang.": "../a-closer-look-1/audio/cau/9dac5f396b6a209e.mp3", "Mi goes to school by bike.": "../communication/audio/cau/c289e58e0081ccad.mp3", "Nam usually goes swimming, but yesterday he went to the park.": "../communication/audio/cau/913dc197023c0f8a.mp3", "Nam is good at maths.": "../getting-started/audio/cau/4fd3587c745c05a2.mp3", "Lan's English is good, but Mi's is better.": "../getting-started/audio/cau/d371c25a8502dc92.mp3", "That's a great idea for our project!": "../communication/audio/cau/a54aafc7aa505f92.mp3", "We had a great time; the trip was wonderful.": "../communication/audio/cau/3dc3e9c44a5960ce.mp3", "Each group has four members.": "../communication/audio/cau/6db9bb96270db26c.mp3", "Work in groups and report your group's findings.": "../communication/audio/cau/dd390edb36c261a2.mp3", "The word 'garden' starts with the letter G.": "../a-closer-look-1/audio/cau/855344adad6266b6.mp3", "Please write a capital G on the board.": "../a-closer-look-1/audio/cau/090b2d929a80461a.mp3", "Let's hang the picture on the wall.": "../a-closer-look-2/audio/cau/562ddbf109c5de04.mp3", "Mi hung her new calendar above her desk.": "../a-closer-look-2/audio/cau/570756d917042d5b.mp3", "Lan has two brothers.": "../a-closer-look-2/audio/cau/3ee04272e80b66c1.mp3", "Nam has a new bike; he had an old one before.": "../a-closer-look-2/audio/cau/756f69898700b7f4.mp3", "My grandmother makes a conical hat every day.": "../a-closer-look-1/audio/cau/785403050e59025d.mp3", "Lan wears a hat, and her brother has two hats.": "../a-closer-look-1/audio/cau/4a6004eb3f79a96b.mp3", "I have a cat and a dog.": "../a-closer-look-1/audio/cau/3942c510ddf250d4.mp3", "We have English today, and we had Maths yesterday.": "../a-closer-look-1/audio/cau/f53b658e1d0dc09e.mp3", "My little brother has a round head.": "../a-closer-look-1/audio/cau/9b2b66e5668763ca.mp3", "Nam has a headache, so his head hurts.": "../a-closer-look-1/audio/cau/ae5fd0fd3be2e909.mp3", "This box is too heavy for me.": "../looking-back/audio/cau/ac63962a8602519b.mp3", "Heavy rain causes floods, and the traffic gets heavier.": "../looking-back/audio/cau/7da989b969861a4f.mp3", "My bedroom is here, next to the kitchen.": "../a-closer-look-2/audio/cau/38f5476965ee13ae.mp3", "Come here, Nam! Your bag is over there.": "../a-closer-look-2/audio/cau/1518838d605d3769.mp3", "We visited Hoi An during the summer holiday.": "../a-closer-look-1/audio/cau/578987a30e37dfd7.mp3", "Lan went on holiday to Da Lat last year.": "../a-closer-look-1/audio/cau/f422a8ac4b914b70.mp3", "In the hot sun, he is always at the school gate.": "../a-closer-look-1/audio/cau/d94f7911dc61672f.mp3", "The heat is terrible today; it's so hot!": "../a-closer-look-1/audio/cau/15a129bda3aabffd.mp3", "We stayed in a small hotel in Hoi An.": "../a-closer-look-2/audio/cau/39dbe04de8de25ad.mp3", "This hotel is near the beach.": "../a-closer-look-2/audio/cau/388cdac8c3071e0f.mp3", "How did he become a famous doctor?": "../a-closer-look-2/audio/cau/0acfb865542d1705.mp3", "How old is Minh, and how does he go to school?": "../a-closer-look-2/audio/cau/0d6be1faa0d18a2b.mp3", "It is important to keep our streets clean.": "../a-closer-look-2/audio/cau/4541b30fbeb1b8aa.mp3", "Reading is important; never forget its importance.": "../a-closer-look-2/audio/cau/0b2b91b8a69bb8c9.mp3", "City life is interesting but stressful.": "../skills-1/audio/cau/d3da66e08dd099e1.mp3", "The film is interesting, and everyone is interested in it.": "../skills-1/audio/cau/4a91c463480dae58.mp3", "My school is big and beautiful.": "../a-closer-look-1/audio/cau/d5765e25cafa0eea.mp3", "Today it is sunny, but yesterday it was rainy.": "../a-closer-look-1/audio/cau/ed1bcaf6501bfd0c.mp3", "Phu Quoc is a beautiful island.": "../a-closer-look-1/audio/cau/f31657f8db0e6c06.mp3", "We took a boat to the island.": "../a-closer-look-1/audio/cau/9d8a709859849b19.mp3", "Ha Long Bay has thousands of islands.": "../a-closer-look-2/audio/cau/be29ea69596d6ca9.mp3", "Viet Nam has many beautiful islands.": "../a-closer-look-2/audio/cau/8ff775d4440744df.mp3", "Nam isn't at home now.": "../a-closer-look-2/audio/cau/064ea182a69f9ba0.mp3", "This is my bag, but that one isn't.": "../a-closer-look-2/audio/cau/93f1c4d3918a4422.mp3", "Minh finished his project just before the due date.": "../communication/audio/cau/6a8c8ece8bd3699e.mp3", "Hoa arrived just before the test started.": "../communication/audio/cau/ddc502e35be5489a.mp3", "The children fly a kite in the park.": "../skills-1/audio/cau/7d867f54ab70c247.mp3", "Nam is flying his new kite on the beach.": "../skills-1/audio/cau/92c4a6d119d60332.mp3", "Don't be late for school!": "../a-closer-look-2/audio/cau/2de1bb7c8bcc4ad3.mp3", "Mi was late, but Nam came early.": "../a-closer-look-2/audio/cau/1f3ff224e4611670.mp3", "She left her hometown at eighteen.": "../looking-back/audio/cau/bac9b0d420a4e9a1.mp3", "We leave at seven; yesterday we left at eight.": "../looking-back/audio/cau/cb394205d90d4293.mp3", "Let's go to the craft village!": "../communication/audio/cau/2c8a106859ac7f9e.mp3", "Let's make lanterns; let us start now.": "../communication/audio/cau/d804af85f9b3cff1.mp3", "I like noodles very much.": "../a-closer-look-2/audio/cau/7557928354c11c4a.mp3", "I like cats, but I dislike spiders.": "../a-closer-look-2/audio/cau/bdd9c25c87fbc823.mp3", "My little brother is five years old.": "../a-closer-look-1/audio/cau/e22af4e6bb3d77f0.mp3", "I have a little money, but my sister has less.": "../a-closer-look-1/audio/cau/520fdc680c743ed9.mp3", "The Mekong is a very long river.": "../a-closer-look-2/audio/cau/962b2d2abaecb121.mp3", "Mi has long hair, but Lan has short hair.": "../a-closer-look-2/audio/cau/21e34cbfd1358b0e.mp3", "Look at the board, please.": "../getting-started/audio/cau/512572a71fea8cfe.mp3", "Look at Minh! He is very good-looking today.": "../getting-started/audio/cau/3a8f3a88e8a3813b.mp3", "Mi is looking for her notebook in the bedroom.": "../getting-started/audio/cau/9cf0853b1a840504.mp3", "Look! Nam is looking at the picture on the wall.": "../getting-started/audio/cau/debf12a72a75e3eb.mp3", "Mai has a lot of friends at school.": "../communication/audio/cau/5010f52a3a68ba0b.mp3", "Minh reads a lot, and he has lots of books.": "../communication/audio/cau/356256a0d64c06ca.mp3", "Don't forget your luggage at the airport.": "../looking-back/audio/cau/847a6537fd23726c.mp3", "My luggage is very heavy.": "../looking-back/audio/cau/4339e0c9ca27e942.mp3", "We have a lot of luggage.": "../looking-back/audio/cau/bd23fa03bc6bd469.mp3", "She carries two pieces of luggage.": "../looking-back/audio/cau/73241d7ed787ba1d.mp3", "I don't eat much meat.": "../a-closer-look-1/audio/cau/b0c3190fea5cd046.mp3", "Mum buys meat at the market.": "../a-closer-look-1/audio/cau/2c086bb181f4e7ea.mp3", "Nice to meet you, Mai!": "../communication/audio/cau/fd0dc2a69403ef29.mp3", "I met Lan yesterday, and we will meet again tomorrow.": "../communication/audio/cau/1a3d6fe8e8cf61b9.mp3", "I drink a glass of milk every morning.": "../a-closer-look-2/audio/cau/0c1e245cf760ba88.mp3", "Lan drinks two glasses of milk a day.": "../a-closer-look-2/audio/cau/51b5c5f3e52b164d.mp3", "I get up at six every morning.": "../skills-1/audio/cau/838c5da1aad62be2.mp3", "We study in the morning and play in the evening.": "../skills-1/audio/cau/8a176d8289d946ce.mp3", "We climbed the mountain on Sunday.": "../a-closer-look-1/audio/cau/3540fe0a0191a696.mp3", "There is snow on the mountain.": "../a-closer-look-1/audio/cau/d6fce88f07e19286.mp3", "Sa Pa has beautiful mountains.": "../skills-1/audio/cau/88d0627a7afe738f.mp3", "We climbed a mountain in a mountainous area.": "../skills-1/audio/cau/86fe451e9e747ae3.mp3", "Ms Hoa teaches us maths.": "audio/cau/f0b35b8376d075b8.mp3", "Ms Lan and Mr Phong are our class teachers.": "audio/cau/6709f6324593fcc8.mp3", "We visited the Museum of Ethnology last Sunday.": "../a-closer-look-2/audio/cau/da984d2ef58da480.mp3", "There are many museums in Ha Noi, and this museum is my favourite.": "../a-closer-look-2/audio/cau/7852c62c0434c444.mp3", "You must wear a uniform at school.": "../a-closer-look-2/audio/cau/46580b2b85391334.mp3", "We must be quiet, and we mustn't run in the classroom.": "../a-closer-look-2/audio/cau/c40bacc8d34e5f31.mp3", "You mustn't run in the classroom.": "../a-closer-look-2/audio/cau/0ed0fba5ab359db1.mp3", "We mustn't litter in the park.": "../a-closer-look-2/audio/cau/9440555771e727e2.mp3", "What is your full name?": "../looking-back/audio/cau/3560e14e0864aa5c.mp3", "Name two products Jobs introduced after 1997.": "../looking-back/audio/cau/2fa79a695478cb53.mp3", "She won a national prize in maths.": "../getting-started/audio/cau/6a93b9368e7abe3a.mp3", "Our nation has many national heroes.": "../getting-started/audio/cau/fe097f04f907a2a9.mp3", "Ha Long Bay is a natural wonder.": "../a-closer-look-2/audio/cau/090f3246ac97d064.mp3", "We should use natural light.": "../a-closer-look-2/audio/cau/6a5bbb9647fc89e3.mp3", "Is it necessary to wear a helmet?": "../a-closer-look-2/audio/cau/310488fddb9b7077.mp3", "Water is necessary for life; it is a basic necessity.": "../a-closer-look-2/audio/cau/1c5a7a36e7e8db29.mp3", "We need more parks in the city.": "../a-closer-look-1/audio/cau/fa790aed3aa20742.mp3", "Plants need water, and Mi needs some help.": "../a-closer-look-1/audio/cau/43af483482c3e17f.mp3", "The village needs a new bridge.": "../a-closer-look-1/audio/cau/1beac53452ba3355.mp3", "Nam needs a pen, and I need one too.": "../a-closer-look-1/audio/cau/bd84b90357a9da88.mp3", "The city is noisy at night.": "../a-closer-look-1/audio/cau/003950b6dbcd9d77.mp3", "We went out last night, so tonight we stay at home.": "../a-closer-look-1/audio/cau/334224d67553dca2.mp3", "She did not give up her dream.": "../a-closer-look-1/audio/cau/b5d39e3052bc5fbb.mp3", "I am not tired, and I'm not hungry.": "../a-closer-look-1/audio/cau/9485504d93b05a38.mp3", "I am doing my homework now.": "../communication/audio/cau/c512289bbb165978.mp3", "It is raining now, so we stay at home.": "../communication/audio/cau/ac1b5a1cae28deb6.mp3", "School starts at seven o'clock.": "../a-closer-look-2/audio/cau/48b40b20309af08c.mp3", "A: I'm sorry I'm late. B: That's OK.": "../communication/audio/cau/1bbe28ae96b898d1.mp3", "Are you OK? You look tired.": "../communication/audio/cau/26aa4543d75a47ea.mp3", "My grandfather is seventy years old.": "../communication/audio/cau/ad4ec0973ce447a3.mp3", "My bike is old, but my sister's bike is new.": "../communication/audio/cau/dc292ece9d402a3f.mp3", "There is only one bed in my bedroom.": "../a-closer-look-2/audio/cau/000e91b12face3a4.mp3", "Lan is an only child; she has just one cousin.": "../a-closer-look-2/audio/cau/b6ec9a93c21bdf30.mp3", "The workers pack the silk scarves into boxes.": "../a-closer-look-1/audio/cau/fb20eff00e9edb32.mp3", "Mi packs her bag, and her mum unpacks it after the trip.": "../a-closer-look-1/audio/cau/328c5412cf5f0d19.mp3", "Read the first paragraph and answer the question.": "../looking-back/audio/cau/43e8d58106b6726a.mp3", "Write a short paragraph of about 80 words.": "../looking-back/audio/cau/79fc537e0a2633c9.mp3", "We often play in the park after school.": "../communication/audio/cau/8d37e1ca664dbf08.mp3", "Dad parks his motorbike near the park gate.": "../communication/audio/cau/54a831b26aaf5a2e.mp3", "Look at the photos of my friends.": "../getting-started/audio/cau/8a988a56d17dddc5.mp3", "Mi takes a photo, and Lan takes many photos.": "../getting-started/audio/cau/df1811e9acc25b9a.mp3", "Pick a card, please.": "../a-closer-look-2/audio/cau/1e4e9d51e347aede.mp3", "We pick tea leaves in the morning.": "../a-closer-look-2/audio/cau/c487a2bfd0d8d890.mp3", "We have a picnic in the park on Sunday.": "../communication/audio/cau/f30198f18ff6ff07.mp3", "Mi brings fruit and cake to the picnic.": "../communication/audio/cau/44d6dc0a4b6ed32f.mp3", "Good planning helps you study better.": "audio/cau/3e380d555c079d24.mp3", "Make a plan for your week and use a planner.": "audio/cau/c7d1745603e5bd75.mp3", "Put a plaster on your finger.": "../a-closer-look-1/audio/cau/50a0278bb14f2ba7.mp3", "I need a plaster for this cut.": "../a-closer-look-1/audio/cau/4553f6fd373eb9ed.mp3", "We keep plasters in the first-aid box.": "../communication/audio/cau/0f0f598fa874d0ae.mp3", "Mum bought some plasters.": "../communication/audio/cau/528beadc8aa6eff9.mp3", "This singer is popular with teenagers.": "../looking-back/audio/cau/fdbd5fd7ebddf922.mp3", "Football is the most popular sport in Viet Nam.": "../looking-back/audio/cau/a567791eb72955db.mp3", "Put your books on the desk.": "../a-closer-look-1/audio/cau/2d454633026296cc.mp3", "Yesterday I put my bike in the garage.": "../a-closer-look-1/audio/cau/4337fe6ef9062f07.mp3", "The rain helps the plants grow.": "../a-closer-look-2/audio/cau/dcb6145c778bef36.mp3", "It is rainy today, so take an umbrella.": "../a-closer-look-2/audio/cau/10a2647a630c9236.mp3", "Take your raincoat with you.": "../communication/audio/cau/544e2999905bea3c.mp3", "My raincoat is yellow.": "../communication/audio/cau/32900658ead8e7a1.mp3", "It's a rainy day today.": "../a-closer-look-1/audio/cau/7487252f9ed5b9ee.mp3", "The rainy season starts in May.": "../a-closer-look-1/audio/cau/041cbb54abf51c95.mp3", "My new friend is really kind.": "../skills-2/audio/cau/abe28633dc1304c0.mp3", "Is this a real photo? Yes, it's really from Ha Long Bay.": "../skills-2/audio/cau/a28021fb9066cf49.mp3", "Lan is wearing a red dress.": "../skills-1/audio/cau/ae3c1aa62302c501.mp3", "The sky is reddish at sunset, and the sun is red.": "../skills-1/audio/cau/6fcd7d055aec1d60.mp3", "Do you remember Mi's birthday?": "../a-closer-look-2/audio/cau/32d012431282fc9b.mp3", "Remember to bring your book; don't forget it!": "../a-closer-look-2/audio/cau/b5bf1b42faeeef1f.mp3", "We eat rice with fish and vegetables.": "../a-closer-look-2/audio/cau/4e526d57f8bd93c3.mp3", "My village grows rice; the rice is very good.": "../a-closer-look-2/audio/cau/0533eb040c5c2035.mp3", "I ride my bike to school every day.": "../skills-1/audio/cau/740570dda66f2738.mp3", "Nam rode his bike to the park yesterday.": "../skills-1/audio/cau/1bec2f7f84326c5b.mp3", "My aunt's house is near the river.": "../getting-started/audio/cau/a6e8ddca094f143a.mp3", "We swim in the river in summer.": "../getting-started/audio/cau/ad856ac1e2451519.mp3", "Be careful when you cross the road.": "../a-closer-look-2/audio/cau/7d44eca76d25a07d.mp3", "This road is busy in the morning.": "../looking-back/audio/cau/84aea104087d60d6.mp3", "The waves hit the rocks.": "../a-closer-look-2/audio/cau/957207024a4e9030.mp3", "Be careful, the rocks are slippery.": "../a-closer-look-2/audio/cau/e04d4cd5c7b350fd.mp3", "Nam picks up litter and other rubbish in the park.": "../looking-back/audio/cau/2004fa74d47adf15.mp3", "Everyone must follow the traffic rules.": "../communication/audio/cau/c4f9d5d2aa3ec721.mp3", "One rule in our city is: don't litter.": "../communication/audio/cau/111e02e3303f9715.mp3", "She's my best friend in class 6A.": "../a-closer-look-1/audio/cau/810592fcf73e04e7.mp3", "This is Vinh's bike, and he's in my class.": "../a-closer-look-1/audio/cau/6a8b8131a5222edf.mp3", "The children are playing in the sand.": "../getting-started/audio/cau/a16a3107b5df90f8.mp3", "The sand on this beach is very white.": "../getting-started/audio/cau/35b49e107c034266.mp3", "The scenery in Sa Pa is beautiful.": "../getting-started/audio/cau/358d4d3d0babffd7.mp3", "We stopped to enjoy the mountain scenery.": "../getting-started/audio/cau/8c1aa30ac773e207.mp3", "Please cut the paper with these scissors.": "../a-closer-look-1/audio/cau/b334dd454f6c7f8d.mp3", "I need a pair of scissors for art class.": "../a-closer-look-1/audio/cau/20b2cb43a4666550.mp3", "Da Nang is famous for fresh seafood.": "../looking-back/audio/cau/834e37db483f266a.mp3", "I can't eat seafood because of allergies.": "../looking-back/audio/cau/3a3fea404f3ed3da.mp3", "Put your shoes on the shoe rack.": "../a-closer-look-2/audio/cau/76db4eca753d1e90.mp3", "Mi has a new pair of shoes for school.": "../a-closer-look-2/audio/cau/9eaab8d6d901e4cb.mp3", "We learn new skills at the English club.": "audio/cau/84d5837cc14182f6.mp3", "Listening is an important skill, and speaking skills are useful too.": "audio/cau/18ae79d29069fa38.mp3", "The baby is sleeping in the bedroom.": "../a-closer-look-1/audio/cau/db81987b31c201bb.mp3", "Shh! Grandpa is sleeping; he slept badly last night.": "../a-closer-look-1/audio/cau/474463118f396d2d.mp3", "My house is small but cosy.": "../getting-started/audio/cau/361843b6d8177bed.mp3", "I live in a small flat, not a big house.": "../getting-started/audio/cau/e341afdae498f225.mp3", "I'm so pleased you won the prize!": "../a-closer-look-1/audio/cau/345d567c5208a7af.mp3", "It was raining, so we stayed at home.": "../a-closer-look-1/audio/cau/d3e8c1c4c40bf63a.mp3", "This is my favourite song.": "audio/cau/541e14c148c17e10.mp3", "Let's sing a song together!": "audio/cau/2582c08c2be3a294.mp3", "Tet is a special time for Vietnamese families.": "../communication/audio/cau/5f60a4fd69577fbf.mp3", "Com is a speciality of Ha Noi, and it's very special.": "../communication/audio/cau/d7109b486b9421a3.mp3", "My grandfather started work when he was fifteen.": "../a-closer-look-1/audio/cau/9cd956a07a50d11d.mp3", "The film started at seven and finished at nine.": "../a-closer-look-1/audio/cau/7b234820845db47a.mp3", "We stay in tents at the summer camp.": "../a-closer-look-1/audio/cau/2e09709e31b8333c.mp3", "Mi will stay at home, but Nam will leave early.": "../a-closer-look-1/audio/cau/d5c48ac441b0c097.mp3", "Each student has a book, and all the students love our teacher.": "../a-closer-look-2/audio/cau/04de8679f0e55800.mp3", "If you eat too much sugar, you may put on weight.": "../a-closer-look-2/audio/cau/00bcdffee9539a79.mp3", "Mai drinks milk without sugar.": "../a-closer-look-2/audio/cau/d6171534c50b9bb9.mp3", "We often go to the beach in summer.": "../a-closer-look-2/audio/cau/3330dd1c522a12fd.mp3", "Summer is hot, but winter is cold in Ha Noi.": "../a-closer-look-2/audio/cau/ed399e7b44a56a6e.mp3", "Put on suncream before you go out.": "../a-closer-look-1/audio/cau/c5e62a63a0184360.mp3", "I always take suncream to the beach.": "../a-closer-look-1/audio/cau/15069821788773f5.mp3", "We have no classes on Sunday.": "../communication/audio/cau/0ddcc7c7e69398d0.mp3", "On Sunday, Minh visits his grandparents.": "../communication/audio/cau/c79a24253c94cc63.mp3", "It is sunny today, so we go to the beach.": "../a-closer-look-1/audio/cau/bf69362fe8f7f110.mp3", "It was a sunny day, so Nam played football in the park.": "../a-closer-look-1/audio/cau/b55154d4fb0d6727.mp3", "Are you sure about the answer?": "../a-closer-look-2/audio/cau/ef07776b14f2052d.mp3", "Nam is sure, but Mi is unsure about it.": "../a-closer-look-2/audio/cau/ab6bc930801198f7.mp3", "I can swim very well.": "../a-closer-look-2/audio/cau/3c5deaf967abfe9e.mp3", "Nam swam in the river yesterday; he is a good swimmer.": "../a-closer-look-2/audio/cau/33e4aee3ddd78677.mp3", "In \"don't\", the letter t comes from not.": "../a-closer-look-1/audio/cau/549e7bc5a2456c75.mp3", "I didn't go out because I was tired.": "../a-closer-look-1/audio/cau/5cc7479c1b749e64.mp3", "Don't forget to take your umbrella.": "../a-closer-look-1/audio/cau/d1c93b06561e343d.mp3", "I take the bus to school; yesterday I took a taxi.": "../a-closer-look-1/audio/cau/6de67298648ceb25.mp3", "Don't drink coffee or tea in the evening.": "../a-closer-look-2/audio/cau/dc61816ecff6c737.mp3", "My grandpa drinks green tea every morning.": "../a-closer-look-2/audio/cau/e84b80f1db559ba1.mp3", "Our English teacher is very kind.": "../a-closer-look-2/audio/cau/4869000a32bce322.mp3", "Ms Hoa taught us maths last year; she is a great teacher.": "../a-closer-look-2/audio/cau/01cfa396481f53ff.mp3", "We slept in a tent at the summer camp.": "../a-closer-look-1/audio/cau/f19fc3ec7e0900aa.mp3", "Nam and Minh put up their tent near the lake.": "../a-closer-look-1/audio/cau/b3574333cb4ba5df.mp3", "The campers stay in tents for three nights.": "../a-closer-look-1/audio/cau/d53570024d363e69.mp3", "Each tent has two beds, and all the tents are near the river.": "../a-closer-look-1/audio/cau/e3d4b45a272af071.mp3", "There is a big garden in my house.": "../a-closer-look-2/audio/cau/94db3c106fafa1ac.mp3", "Your bag is here, and my bag is over there.": "../a-closer-look-2/audio/cau/37204e4c7e951d02.mp3", "I put my things in my schoolbag.": "../a-closer-look-1/audio/cau/bf35bafff88418e4.mp3", "There are many good things at my school, not just one thing.": "../a-closer-look-1/audio/cau/26ddc5ba45fd5524.mp3", "What time is it now, Mum?": "../a-closer-look-1/audio/cau/1cbca6b4e0afa66c.mp3", "Look at the timetable; it is time for maths.": "../a-closer-look-1/audio/cau/9b6fb48058293171.mp3", "Today is Monday, and I have maths.": "../a-closer-look-1/audio/cau/a2c1db38d6bad1f7.mp3", "It is sunny today, so we play outside.": "../a-closer-look-1/audio/cau/43f448f8abe01280.mp3", "I like swimming, and my sister likes it too.": "../communication/audio/cau/695ee0e76ca64b23.mp3", "This tea is too hot; I also want some water.": "../communication/audio/cau/641c64a35c7075e8.mp3", "A tourist asked me the way to the lake.": "../communication/audio/cau/85504a3dd570c415.mp3", "Tourism is important, and every tourist loves our pho.": "../communication/audio/cau/28ec58cef47dd36f.mp3", "Many tourists visit Hoi An every year.": "../looking-back/audio/cau/34e133dcd9a0fdd4.mp3", "The market attracts tourists and locals.": "../looking-back/audio/cau/4d4408900393fd12.mp3", "I want to travel around Viet Nam.": "../a-closer-look-1/audio/cau/0750a29d21b5efe2.mp3", "He travelled a lot; he was a real traveller.": "../a-closer-look-1/audio/cau/4dcdae3874eeaed4.mp3", "There are many old trees in my village.": "../looking-back/audio/cau/826dbf2b122a8fa0.mp3", "My grandfather planted this tree twenty years ago.": "../looking-back/audio/cau/dc3f88c985c7e66b.mp3", "Our class went on a trip to Ba Vi last week.": "../communication/audio/cau/49052bb2aa4887c3.mp3", "The school trip was fun, and Minh enjoyed the journey.": "../communication/audio/cau/4af60768714d1058.mp3", "Is it true that Nam can sing well?": "../skills-2/audio/cau/b793f0302657ab80.mp3", "The story is true, not false.": "../skills-2/audio/cau/fd6a61c02d4b7fe6.mp3", "My school is very big and beautiful.": "../a-closer-look-1/audio/cau/5cd4ea7091dbf666.mp3", "Thank you very much for your help.": "../a-closer-look-1/audio/cau/162955bdaf4118ee.mp3", "My grandparents live in a small village.": "../a-closer-look-1/audio/cau/959ff3761670ea0d.mp3", "The villagers in our village grow rice.": "../a-closer-look-1/audio/cau/c5c92b3fc554d83c.mp3", "Visit our website for more information.": "../communication/audio/cau/ac9737600d9243d7.mp3", "Phong visited his grandparents, and they enjoyed his visit.": "../communication/audio/cau/24f2a12ad9734414.mp3", "We wait for the bus every morning.": "audio/cau/8f6fa20987613133.mp3", "Lan waited for Nam for twenty minutes.": "audio/cau/414ea15ff7f26c66.mp3", "I want to go to the summer camp.": "../a-closer-look-1/audio/cau/16ac9d133b953dea.mp3", "Minh wanted a new bike, and he still wants one.": "../a-closer-look-1/audio/cau/74bcc5e39e26178a.mp3", "It's warm today.": "../a-closer-look-1/audio/cau/cc0e8ca9006d57a2.mp3", "Wear a warm coat in winter.": "../a-closer-look-1/audio/cau/95aec6c826de01b5.mp3", "Can I have some water, please?": "../a-closer-look-1/audio/cau/e7f9c90ffdf43ef9.mp3", "Hoa waters the plants with rainwater.": "../a-closer-look-1/audio/cau/63d57a63a01495bc.mp3", "Ban Gioc is a famous waterfall.": "../a-closer-look-1/audio/cau/05ee9351d0acfcba.mp3", "We swam near the waterfall.": "../a-closer-look-1/audio/cau/f8727faaedec9a8d.mp3", "My watch is waterproof.": "../communication/audio/cau/85db747944c36d44.mp3", "Bring a waterproof jacket.": "../communication/audio/cau/ad51a5688af0af57.mp3", "Workers wear helmets at work.": "../skills-1/audio/cau/58cc64267deb5ef1.mp3", "Mi usually wears jeans, but yesterday she wore a dress.": "../skills-1/audio/cau/23bb4a0107f750d1.mp3", "My shoes are wet.": "audio/cau/02a574a508239da2.mp3", "Don't touch the wet paint.": "audio/cau/56ef844dc3e18a1e.mp3", "Where do you live, Lan?": "../a-closer-look-1/audio/cau/0c6d7d3df1a25694.mp3", "Where is my schoolbag, Mum?": "../a-closer-look-1/audio/cau/57a3c3d221996a0d.mp3", "Where's the bed? It's next to the window.": "../a-closer-look-1/audio/cau/640eff7ddd6c8116.mp3", "Where's Nick's bag? It's under the bed.": "../a-closer-look-1/audio/cau/36d364164efec528.mp3", "Ha Long Bay is a natural wonder of Viet Nam.": "../a-closer-look-1/audio/cau/b6c81cae87b891ea.mp3", "I wonder what my new teacher is like.": "../a-closer-look-1/audio/cau/2d41b1bac533182b.mp3", "We had a wonderful holiday.": "../a-closer-look-1/audio/cau/b731d7b223c248dd.mp3", "What a wonderful idea!": "../a-closer-look-1/audio/cau/83d5b6cb831dd9a7.mp3", "Learn five new words every day.": "../a-closer-look-1/audio/cau/adb2b8f5372e6050.mp3", "Match the words with the pictures, one word for each picture.": "../a-closer-look-1/audio/cau/0c015f99a499421d.mp3", "Please write your name here.": "../a-closer-look-1/audio/cau/a728b2e865ff5c76.mp3", "Mi likes to write, and she wrote a story yesterday.": "../a-closer-look-1/audio/cau/a907f42938059961.mp3", "She was writing a book when I phoned her.": "../a-closer-look-1/audio/cau/97a3ce971a3a7562.mp3", "Mi is writing a letter, and she wrote one yesterday too.": "../a-closer-look-1/audio/cau/f5189e5fac049044.mp3", "There are twelve months in a year.": "audio/cau/5ae786ad7493bc72.mp3", "This year, Mi is in Grade 9.": "audio/cau/6bad90fc27f44b2c.mp3", "'Beds' ends with the sound /z/, like the letter z.": "../a-closer-look-1/audio/cau/3f3d119d536ccc70.mp3", "In British English, we say 'zed' for the letter z.": "../a-closer-look-1/audio/cau/a4ee8fbe573fdd5e.mp3"};
